import type { Plugin, PluginContext } from "../../kernel/types";

// Provider definition: id/label/defaultModel + chat async generator.
// The chat generator only emits: one delta text "LOCAL-OK", a usage block
// (input=1/output=1), and a final done marker. No network, no tools.
const provider = {
  id: "local-response",
  label: "Local",
  defaultModel: "local",
  async *chat(_req: any, _tctx: any): AsyncGenerator<any, void, unknown> {
    yield { type: "delta", text: "LOCAL-OK" };
    yield { type: "usage", input: 1, output: 1 };
    yield { type: "done" };
  },
};

export default {
  id: "local-provider",
  name: "Local Provider",
  version: "1.0.0",
  onLoad(ctx: PluginContext) {
    ctx.register({ kind: "provider", provider } as any);
  },
} as Plugin;

